 33	assert_command_output() {
 34	    local description="$1"
 35	    local shape="$2"
 36	    local contains="$3"
 37	    local not_contains="$4"
 38	    local home="$5"
 39	    shift 5
 40	
 41	    local output
 42	    if ! output="$(env -i PATH="${PATH:-}" HOME="$home" "$@" 2>&1)"; then
 43	        fail "$description"
 44	        echo "    hook exited non-zero"
 45	        echo "$output" | sed 's/^/      /'
 46	        return
 47	    fi
 48	
 49	    if printf '%s' "$output" | \
 50	        EXPECT_SHAPE="$shape" \
 51	        EXPECT_CONTAINS="$contains" \
 52	        EXPECT_NOT_CONTAINS="$not_contains" \
 53	        node -e '
 54	const fs = require("fs");
 55	
 56	const input = fs.readFileSync(0, "utf8");
 57	let payload;
 58	try {
 59	  payload = JSON.parse(input);
 60	} catch (error) {
 61	  console.error(`invalid JSON: ${error.message}`);
 62	  process.exit(1);
 63	}
 64	
 65	function hasOwn(object, key) {
 66	  return Object.prototype.hasOwnProperty.call(object, key);
 67	}
 68	
 69	function fail(message) {
 70	  console.error(message);
 71	  process.exit(1);
 72	}
 73	
 74	const shape = process.env.EXPECT_SHAPE;
 75	let context;
 76	
 77	if (shape === "nested") {
 78	  if (!hasOwn(payload, "hookSpecificOutput")) {
 79	    fail("missing hookSpecificOutput");
 80	  }
 81	  if (hasOwn(payload, "additional_context") || hasOwn(payload, "additionalContext")) {
 82	    fail("nested output also included a top-level context field");
 83	  }
 84	  const hookOutput = payload.hookSpecificOutput;
 85	  if (!hookOutput || typeof hookOutput !== "object" || Array.isArray(hookOutput)) {
 86	    fail("hookSpecificOutput is not an object");
 87	  }
 88	  if (hookOutput.hookEventName !== "SessionStart") {
 89	    fail(`unexpected hookEventName: ${hookOutput.hookEventName}`);
 90	  }
 91	  context = hookOutput.additionalContext;
 92	} else if (shape === "cursor") {
 93	  if (hasOwn(payload, "hookSpecificOutput")) {
 94	    fail("cursor output included hookSpecificOutput");
 95	  }
 96	  if (!hasOwn(payload, "additional_context")) {
 97	    fail("cursor output missing additional_context");
 98	  }
 99	  if (hasOwn(payload, "additionalContext")) {
100	    fail("cursor output included additionalContext");
101	  }
102	  context = payload.additional_context;
103	} else if (shape === "sdk") {
104	  if (hasOwn(payload, "hookSpecificOutput")) {
105	    fail("sdk output included hookSpecificOutput");
106	  }
107	  if (!hasOwn(payload, "additionalContext")) {
108	    fail("sdk output missing additionalContext");
109	  }
110	  if (hasOwn(payload, "additional_context")) {
111	    fail("sdk output included additional_context");
112	  }
113	  context = payload.additionalContext;
114	} else {
115	  fail(`unknown expected shape: ${shape}`);
116	}
117	
118	if (typeof context !== "string" || context.trim() === "") {
119	  fail("injected context was empty");
120	}
121	
122	const expectedText = process.env.EXPECT_CONTAINS || "";
123	if (expectedText && !context.includes(expectedText)) {
124	  fail(`context did not contain expected text: ${expectedText}`);
125	}
126	
127	const forbiddenTexts = (process.env.EXPECT_NOT_CONTAINS || "")
128	  .split("\u001f")
129	  .filter(Boolean);
130	for (const forbiddenText of forbiddenTexts) {
131	  if (context.includes(forbiddenText)) {
132	    fail(`context contained forbidden text: ${forbiddenText}`);
133	  }
134	}
135	'; then
136	        pass "$description"
137	    else
138	        fail "$description"
139	        echo "    output:"
140	        echo "$output" | sed 's/^/      /'
141	    fi
142	}
143	
144	echo "SessionStart hook output tests"
145	
146	# Registration shape: the hook must declare shell:"bash" so Claude Code on
147	# Windows dispatches via Git Bash (or fails with an actionable error) instead
148	# of PowerShell/cmd.exe, whose parsers break on the quoted command string
149	# (PowerShell ParserError; cmd.exe quote-stripping on paths with metacharacters).
150	if node -e '
151	const hooks = JSON.parse(require("fs").readFileSync(process.argv[1], "utf8"));
152	const entry = hooks.hooks.SessionStart[0].hooks[0];
153	if (entry.shell !== "bash") {
154	  console.error(`SessionStart hook shell is ${JSON.stringify(entry.shell)}, expected "bash"`);
155	  process.exit(1);
156	}
157	if (!/run-hook\.cmd" session-start$/.test(entry.command)) {
158	  console.error(`unexpected SessionStart command shape: ${entry.command}`);
159	  process.exit(1);
160	}
  1	#!/usr/bin/env bash
  2	set -euo pipefail
  3	
  4	SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
  5	REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
  6	HOOK_UNDER_TEST="$REPO_ROOT/hooks/session-start-codex"
  7	CONFIG_UNDER_TEST="$REPO_ROOT/hooks/hooks-codex.json"
  8	
  9	FAILURES=0
 10	
 11	pass() {
 12	    echo "  [PASS] $1"
 13	}
 14	
 15	fail() {
 16	    echo "  [FAIL] $1"
 17	    FAILURES=$((FAILURES + 1))
 18	}
 19	
 20	# run_hook <stdin-payload> — echoes hook stdout; fails the calling test on
 21	# non-zero exit. env -i mirrors the codex hook executor's clean environment.
 22	run_hook() {
 23	    printf '%s' "$1" | env -i PATH="${PATH:-}" bash "$HOOK_UNDER_TEST"
 24	}
 25	
 26	echo "Codex SessionStart hook tests"
 27	
 28	startup_payload='{"session_id":"s","hook_event_name":"SessionStart","model":"gpt-5.6-terra","source":"startup"}'
 29	if output="$(run_hook "$startup_payload")" && [ -z "$output" ]; then
 30	    pass "source=startup emits nothing and exits 0"
 31	else
 32	    fail "source=startup emits nothing and exits 0"
 33	    printf '%s\n' "$output" | head -3 | sed 's/^/    /'
 34	fi
 35	
 36	compact_payload='{"session_id":"s","hook_event_name":"SessionStart","model":"gpt-5.6-terra","source":"compact"}'
 37	if output="$(run_hook "$compact_payload")"; then
 38	    ok=1
 39	    for needle in \
 40	        "<EXTREMELY_IMPORTANT>" \
 41	        "You have superpowers." \
 42	        "name: using-superpowers" \
 43	        "<CONTEXT_RESTORED>" \
 44	        "subagent-driven-development/SKILL.md" \
 45	        "references/codex-tools.md"; do
 46	        if [[ "$output" != *"$needle"* ]]; then
 47	            ok=0
 48	            echo "    missing: $needle"
 49	        fi
 50	    done
 51	    if [ "$ok" -eq 1 ]; then
 52	        pass "source=compact emits bootstrap plus re-read addendum"
 53	    else
 54	        fail "source=compact emits bootstrap plus re-read addendum"
 55	    fi
 56	else
 57	    fail "source=compact emits bootstrap plus re-read addendum (hook exited non-zero)"
 58	fi
 59	
 60	# Whitespace-tolerant source matching (serializers vary).
 61	spaced_payload='{"hook_event_name":"SessionStart", "source" : "compact"}'
 62	if output="$(run_hook "$spaced_payload")" && [[ "$output" == *"<CONTEXT_RESTORED>"* ]]; then
 63	    pass "whitespace around the source key still triggers injection"
 64	else
 65	    fail "whitespace around the source key still triggers injection"
 66	fi
 67	
 68	if output="$(printf '' | env -i PATH="${PATH:-}" bash "$HOOK_UNDER_TEST")" && [ -z "$output" ]; then
 69	    pass "empty stdin fails open to no output, exit 0"
 70	else
 71	    fail "empty stdin fails open to no output, exit 0"
 72	fi
 73	
 74	if output="$(run_hook 'not json at all {{{')" && [ -z "$output" ]; then
 75	    pass "garbage stdin fails open to no output, exit 0"
 76	else
 77	    fail "garbage stdin fails open to no output, exit 0"
 78	fi
 79	
 80	# A compact mention inside some other field must not trigger injection.
 81	decoy_payload='{"hook_event_name":"SessionStart","source":"startup","cwd":"/tmp/compact"}'
 82	if output="$(run_hook "$decoy_payload")" && [ -z "$output" ]; then
 83	    pass "compact appearing outside the source field does not trigger"
 84	else
 85	    fail "compact appearing outside the source field does not trigger"
 86	fi
 87	
 88	if node -e '
 89	const config = JSON.parse(require("fs").readFileSync(process.argv[1], "utf8"));
 90	const group = config.hooks.SessionStart[0];
 91	if (group.matcher !== "compact") {
 92	  console.error(`hook matcher is ${JSON.stringify(group.matcher)}, expected "compact"`);
 93	  process.exit(1);
 94	}
 95	const entry = group.hooks[0];
 96	if (entry.type !== "command") {
 97	  console.error(`hook type is ${JSON.stringify(entry.type)}, expected "command"`);
 98	  process.exit(1);
 99	}
100	if (!entry.command.includes("${PLUGIN_ROOT}") || !/run-hook\.cmd" session-start-codex$/.test(entry.command)) {
101	  console.error(`unexpected command shape: ${entry.command}`);
102	  process.exit(1);
103	}
104	' "$CONFIG_UNDER_TEST"; then
105	    pass "hooks-codex.json runs session-start-codex via \${PLUGIN_ROOT} on compact"
106	else
107	    fail "hooks-codex.json runs session-start-codex via \${PLUGIN_ROOT} on compact"
108	fi
109	
110	if [[ "$FAILURES" -gt 0 ]]; then
111	    echo "STATUS: FAILED ($FAILURES failure(s))"
112	    exit 1
113	fi
114	
115	echo "STATUS: PASSED"
